mapper.select:
SELECT
    lyr.id layerId,
    lyr.layer_name layerName,
    lyr.custom_name layerCustomName
FROM
    sys_layer lyr
WHERE
    lyr.delete_flag IS FALSE
  AND lyr.tenant_id = #{dto.tenantId}
  AND lyr.industry_code = #{dto.industryCode}
  AND lyr.create_time IS NOT NULL
  AND lyr.layer_name IS NOT NULL
  AND lyr.maxx > ${geoExtent.minX}
  AND lyr.minx < ${geoExtent.maxX}
  AND lyr.maxy > ${geoExtent.minY}
  AND lyr.miny < ${geoExtent.maxY}
    ${dto.dataPermissions}

SELECT EXISTS (
    SELECT 1 FROM pg_catalog.pg_tables
    WHERE tablename = #{tableName}
);

mapper.insert:
CREATE SEQUENCE ${tableName}_id_seq
    INCREMENT 1
            START 1
            MINVALUE 1
            MAXVALUE 2147483647
            CACHE 1;

CREATE TABLE IF NOT EXISTS ${tableName}
(
    id integer NOT NULL DEFAULT nextval('${tableName}_id_seq'::regclass),
    geom geometry,
    bsm	character varying(50) COLLATE pg_catalog."default",
    dlbm	character varying(20) COLLATE pg_catalog."default",
    dlmc	character varying(20) COLLATE pg_catalog."default",
    calarea	double precision,
    tbmj	double precision,
    create_time timestamp with time zone,
    CONSTRAINT ${tableName}_pkey PRIMARY KEY (id)
    );

ALTER SEQUENCE ${tableName}_id_seq OWNED BY ${tableName}.id;
CREATE INDEX ${tableName}_geom_idx ON ${tableName} USING gist (geom);

mapper.select:
SELECT
    LOWER ( lyrtp.abbreviation ) layerTypeSimple
FROM
    sys_layer lyr,
    sys_layer_type lyrtp
WHERE
    lyr.delete_flag IS FALSE
  AND lyr.layer_type_id = lyrtp.id
  AND lyr.tenant_id =  #{dto.tenantId}
  AND lyr.industry_code = #{dto.industryCode}
  AND lyr.layer_name = #{tableName}
  ${dto.dataPermissions}
